import type { Metadata } from "next";
import { absoluteUrl, siteConfig } from "@/lib/site";
import { ogSize } from "./og";

/** Site-wide social image generated by app/opengraph-image.tsx. */
const defaultImage = {
  url: "/opengraph-image",
  ...ogSize,
  alt: "Breno Rocha: Analista de Dados Júnior",
};

type PageMetadataInput = {
  /** Page title (the layout template appends " | Breno Rocha" unless `absoluteTitle`). */
  title: string;
  description: string;
  /** Site-relative path, e.g. "/sobre". */
  path: string;
  /** Title used in social cards when it should differ from <title>. */
  socialTitle?: string;
  type?: "website" | "article";
  /** Uses the title as is, without the layout template (Home). */
  absoluteTitle?: boolean;
  /**
   * false when the route has its own opengraph-image.tsx (project pages). Otherwise the
   * site-wide image is set explicitly: a page `openGraph` replaces the parent's file image.
   */
  defaultSocialImage?: boolean;
};

/**
 * Next.js merges `openGraph`/`twitter` shallowly: a page that sets them drops the
 * layout's siteName/locale/type/card. This helper always re-applies them.
 */
export function pageMetadata({
  title,
  description,
  path,
  socialTitle,
  type = "website",
  absoluteTitle = false,
  defaultSocialImage = true,
}: PageMetadataInput): Metadata {
  const url = absoluteUrl(path);
  const ogTitle = socialTitle ?? title;
  const images = defaultSocialImage ? { images: [defaultImage] } : {};
  return {
    title: absoluteTitle ? { absolute: title } : title,
    description,
    alternates: { canonical: url },
    openGraph: {
      type,
      locale: siteConfig.locale,
      siteName: siteConfig.name,
      title: ogTitle,
      description,
      url,
      ...images,
    },
    twitter: { card: "summary_large_image", title: ogTitle, description, ...images },
  };
}
